		To      string   `json:"to"`
		Targets []string `json:"targets"`
		Depth   int      `json:"depth"`
		Budget  int      `json:"budget"`
	}
	if err := decode(call, &args); err != nil {
		return tools.Errorf("bad arguments: %v", err)
	}
